//------------------------------------------------------------------------------
// Interface: client_rx_if
//
// This interface defines all the ports of CLIENT_RX Agent.
// There are modports and clocking blocks that facilitate the signal toggling.
//
//------------------------------------------------------------------------------
interface client_rx_if #(
   `ifdef CLIENT_RX__PARAM_ANSI
      `CLIENT_RX__PARAM_ANSI,
   `endif
   parameter                 FP_WIDTH                    = 8,
   parameter                 FP_WIDTH_BIT_CHANGE         = (NUM_WORDS < 16) ? FP_WIDTH : (FP_WIDTH*2),	
   parameter                 WIDTH_0_TO_1_BIT_CHANGE     = (NUM_WORDS < 16) ?0 : 1, 
   parameter                 WIDTH_7_TO_15_BIT_CHANGE    = (NUM_WORDS < 16) ?7 : 15,
   parameter                 WIDTH_6_TO_13_BIT_CHANGE    = (NUM_WORDS < 16) ?6 : 13,
   parameter                 WIDTH_15_TO_31_BIT_CHANGE   = (NUM_WORDS < 16) ?15 : 31,
   parameter                 WIDTH_95_TO_191_BIT_CHANGE  = (NUM_WORDS < 16) ?95: 191,

    // Clocking block's output delay versus the clock period
   parameter   real           OUT_DELAY_RATIO = 0,
   parameter                 WIDTH_4_TO_9_BIT_CHANGE                            = 4
) (input logic clk, rst_n);



   //---------------------------------------------------------------------------
   // Local parameters.
   //---------------------------------------------------------------------------
// <<example>>: localparam                 ADDR_WIDTH = DATA_WIDTH;

   //---------------------------------------------------------------------------

// <<example>>: logic [DATA_WIDTH-1:0] wdata;
// <<example>>: logic [DATA_WIDTH-1:0] rdata;
// <<example>>: logic                  wvalid;
// <<example>>: logic                  rvalid;
   logic [DATA_WIDTH-1:0]          data[NUM_WORDS];
   logic [IN_FRAME_WIDTH-1:0]      in_frame[NUM_WORDS];
   logic [EOP_EMPTY_WIDTH-1:0]     eop_empty[NUM_WORDS];
   logic [RX_STATUS_WIDTH-1:0]     rx_status[NUM_WORDS];
   bit   [RX_STATUS_WIDTH-1:0]     rx_status_variable[NUM_WORDS]; 
   logic [RX_ERROR_WIDTH-1:0]      rx_error[NUM_WORDS];
   bit [RX_ERROR_WIDTH-1:0]        rx_error_variable[NUM_WORDS];
   logic                           fcs_error[NUM_WORDS];
   bit 				   fcs_error_variable[NUM_WORDS];
   logic                           vld;
   logic                           rdy;
   logic                           local_fault;
   logic                           remote_fault;
   logic [7:0]                     pfc;
   logic                           pause;
   logic                           word_align[NUM_WORDS];
   logic                           user_mode;
   logic                           ptp_rx_ts;
   logic 		           o_rx_am[NUM_WORDS];
   logic [1:0]                     ptp_word_align;
   logic [WIDTH_95_TO_191_BIT_CHANGE:0]  o_ptp_ets; 			//Unused - using ptp_tx_mon to sample
   logic [WIDTH_0_TO_1_BIT_CHANGE: 0]    o_ptp_ets_valid;   //Unused - using ptp_tx_mon to sample
   //logic [WIDTH_7_TO_15_BIT_CHANGE:0]    o_ptp_ets_fp;
   logic [FP_WIDTH_BIT_CHANGE-1:0]       o_ptp_ets_fp;      //Unused - using ptp_tx_mon to sample
   logic [WIDTH_95_TO_191_BIT_CHANGE:0]  o_ptp_rx_its;      //Unused - using ptp_tx_mon to sample
   logic [WIDTH_4_TO_9_BIT_CHANGE:0]     o_ptp_ets_vl;      //Unused - using ptp_tx_mon to sample
   logic                                 o_ptp_rx_sop;
   logic [WIDTH_0_TO_1_BIT_CHANGE : 0]   o_ptp_rx_valid;
   bit [EOP_EMPTY_WIDTH-1:0] empty_variable[NUM_WORDS]; 
   
   logic                           found_sop; //a pulse
   int                             found_sop_pos[$];
   int                             found_eop_pos[$];
   logic [NUM_WORDS-1:0] 		   sop; 
   logic [NUM_WORDS-1:0] 		   eop; 
   logic                           found_eop;
   logic 						   in_frame_prev;
   //For ptp tx monitor
   logic                           found_sop_lower;
   logic                           found_sop_upper;   

   //---------------------------------------------------------------------------
   // Internal Variables and Assignments
   //---------------------------------------------------------------------------
   // Variable which contain the clock cycle's period
   time                       clock_period;
   

   //---------------------------------------------------------------------------
   // Detecting the clock period automatically
   //---------------------------------------------------------------------------
   initial begin : b_DETECT_CLOCK_PERIOD
      time     start_time;
      // Repeat for every reset de-asserted
      // This is to ensure that the clock is stable
      forever @ (posedge clk) begin
         // Capture the time of the first rising edge
         start_time = $time;
         // Capture the time of the second rising edge and
         // calculate the clock period
         @ (posedge clk);
         clock_period = $time - start_time;
      end
   end : b_DETECT_CLOCK_PERIOD

 always@(posedge clk) begin 
   	if(vld)
   	in_frame_prev<=in_frame[NUM_WORDS-1];
	end

   always@(negedge clk)
   begin 
   	//foreach(sop[i]) begin --> order is reverse if there is multi sop as the variable is non array. 
      //The foreach-loop arranges for higher cardinality indices to change more rapidly. SV LRM 1800-2012, 12.7.3
      for(int i=0; i < NUM_WORDS; i++)begin
   		if(sop[i]==1) begin 
   			found_sop_pos.push_back(i); 
   		end 
   	end
   end

   always@(negedge clk)
   begin 
   	//foreach(eop[i]) begin --> order is reverse if there is multi sop as the variable is non array. 
      //The foreach-loop arranges for higher cardinality indices to change more rapidly. SV LRM 1800-2012, 12.7.3
      for(int i=0; i < NUM_WORDS; i++)begin
   		if(eop[i]==1) begin 
   			found_eop_pos.push_back(i); 
   		end 
   	end
   end
   
   assign sop[0]= (in_frame[0]&&(!in_frame_prev)&&vld);
    for(genvar i=0; i<NUM_WORDS-1;i++)
    assign sop[i+1]= (in_frame[i+1]&&(!in_frame[i])&&vld);
   assign found_sop= |(sop);

   //eop 
   assign eop[0]= ((!in_frame[0])&& in_frame_prev&&vld);
    for(genvar i=0; i<NUM_WORDS-1;i++)
    assign eop[i+1]= (in_frame[i]&&(!in_frame[i+1])&&vld);
   assign found_eop= |(eop);
  
    
if(NUM_WORDS ==16)
  begin
    assign found_sop_lower = ((sop[0]) || (sop[1] ) || (sop[2] ) || (sop[3] ) ||
                               (sop[4] ) || (sop[5] ) || (sop[6] ) || (sop[7] ));
    assign found_sop_upper = ((sop[8]) || (sop[9] ) || (sop[10] ) || (sop[11] ) ||
                              (sop[12] ) || (sop[13] ) || (sop[14] ) || (sop[15] ));
   end

if(NUM_WORDS ==8)
begin
   assign found_sop_lower = ((sop[0]) || (sop[1]) || (sop[2]) || (sop[3]) || (sop[4]) || (sop[5]) || (sop[6]) || (sop[7]));
    //assign found_sop_upper = ((sop[4]) || (sop[5]) || (sop[6]) || (sop[7]) );
end
 

if(NUM_WORDS ==4)
begin
   assign found_sop_lower = ((sop[0]) || (sop[1])|| (sop[2]) || (sop[3]));
   // assign found_sop_upper= ((sop[2]) || (sop[3]) );
end

if(NUM_WORDS ==2)
begin
    assign found_sop_lower = ((sop[0]) || (sop[1]));
    //assign found_sop_upper= ( (sop[1]));
end

if(NUM_WORDS ==1)
begin
    assign found_sop_lower = (sop[0]);
end
    
      //---------------------------------------------------------------------------
   // Clocking block declarations.
   //---------------------------------------------------------------------------
   clocking mst_cb @ (posedge clk);
      default input #1step output #(clock_period * OUT_DELAY_RATIO);
// <<example>>: output wdata;
// <<example>>: input  rdata;
// <<example>>: input  wvalid;
// <<example>>: input  rvalid;
      
   endclocking : mst_cb

   clocking mon_cb @ (posedge clk);
      default input #1step output #(clock_period * OUT_DELAY_RATIO);
// <<example>>: input  wdata;
// <<example>>: input  rdata;
// <<example>>: input  wvalid;
// <<example>>: input  rvalid;
      input data;
      input in_frame;
      input in_frame_prev;
      input eop_empty;
      input rx_status;
      input rx_error;
      input fcs_error;
      input vld;
      input rdy;
      input local_fault;
      input remote_fault;
      input pfc;
      input pause;
      input word_align;
      input ptp_word_align;
      input user_mode;
      input ptp_rx_ts;
      input o_rx_am;
      input o_ptp_ets;
      input o_ptp_ets_valid;
      input o_ptp_ets_fp;
      input o_ptp_rx_its;
      input o_ptp_ets_vl;
      input o_ptp_rx_sop;
      input o_ptp_rx_valid;
      input found_sop;
      input found_eop;
      input found_sop_lower;
      input found_sop_upper;
   endclocking : mon_cb

   //---------------------------------------------------------------------------
   // Modports declaration.
   //---------------------------------------------------------------------------
   modport mst_mp (
      input    clk,
      input    rst_n,
      clocking mst_cb,
   // Refrenced the signals driven asynchronously without clocking block
// <<example>>: ref      wdata,
// <<example>>: ref      rdata,
// <<example>>: ref      wvalid,
// <<example>>: ref      rvalid,
   // Referenced local variables to be visiber in modport level
      ref      clock_period
   );

   modport mon_mp (
      input    clk,
      input    rst_n,
      clocking mon_cb,
      ref      clock_period
   );

property signal_unknown(signal); 
	@(posedge clk) disable iff(vld!==1) $isunknown(signal)==0; 
endproperty 

for(genvar i=0; i<NUM_WORDS;i++)
begin
	assert property (signal_unknown(data[i])) else 
	`uvm_error("signal_unknown",$sformatf("data is x or z when valid is high"));
	assert property (signal_unknown(in_frame[i])) else 
	`uvm_error("signal_unknown",$sformatf("in_frame is x or z when valid is high"));
	assert property (signal_unknown(eop_empty[i])) else 
	`uvm_error("signal_unknown",$sformatf("eop_empty is x or z when valid is high"));
	assert property (signal_unknown(rx_status[i])) else 
	`uvm_error("signal_unknown",$sformatf("skip_crc is x or z when valid is high"));
	assert property (signal_unknown(rx_error[i])) else 
	`uvm_error("signal_unknown",$sformatf("skip_crc is x or z when valid is high"));
	assert property (signal_unknown(fcs_error[i])) else 
	`uvm_error("signal_unknown",$sformatf("tx_error is x or z when valid is high"));
end

for(genvar i=0; i<NUM_WORDS;i++)
begin 
	property sop_eop; 
		@(posedge clk)
		disable iff(rst_n&vld !==1)
		!((sop[i]&&eop[i]));
	endproperty 
/*	assert property (sop_eop) else //FIXME
	`uvm_error("sop_eop", $sformatf("sop & eop are asserted at the same clock event")); */
	for(genvar j=0; j!=i;j++)
	begin
		property eop_aligned(signal); 
			@(posedge clk)
			disable iff(rst_n!==1)
			eop[i]|->(!signal[j]);
		endproperty 
	//	assert property (eop_aligned(eop_empty)) else  //empty bytes
	//	can be non zero on non eop segments. 
	//	`uvm_error("eop_aligned", $sformatf("empty bits of non-eop segment has a non zero value"));
//		assert property (eop_aligned(fcs_error)) else 
//		`uvm_error("eop_aligned", $sformatf("empty bits of non-eop segment has a non zero value"));
		// dsamantx: commented as its ok to have non eop segments to have rx_error toggling from the recent update we got from the design engineers. 
		//assert property (eop_aligned(rx_error)) else 
		//`uvm_error("eop_aligned", $sformatf("empty bits of non-eop segment has a non zero value"));
//		assert property (eop_aligned(rx_status)) else 
//		`uvm_error("eop_aligned", $sformatf("empty bits of non-eop segment has a non zero value"));
	end
end 
for(genvar i=0; i<NUM_WORDS;i++)
begin 
	property sop_b2b; 
		@(posedge clk)
		disable iff(rst_n&vld !==1)
		if(i!=NUM_WORDS-1)
		!(sop[i]&&sop[i+1])
		else
		$past(rst_n&vld,1)!==1 |-> !($past(sop[NUM_WORDS-1],1)&&sop[0]);
	endproperty 
	property eop_b2b; 
		@(posedge clk)
		disable iff(rst_n&vld !==1)
		if(i!=NUM_WORDS-1)
		!(eop[i]&&eop[i+1])
		else
		$past(rst_n&vld,1)!==1 |-> !($past(eop[NUM_WORDS-1],1)&&eop[0]);
	endproperty
	//assert property (sop_b2b) else 
	//`uvm_error("sop_b2b", $sformatf("sop in back to back segments"));
	//assert property (eop_b2b) else 
	//`uvm_error("sop_b2b", $sformatf("eop in back to back segments"));
end  

//   `include "client_rx_if_sva.sv"
//sop & eop onehot values 
// workaround to collect coverage on net datatype 
for(genvar i=0; i<NUM_WORDS;i++)
begin 
	always @(eop_empty[i])  
		empty_variable[i]=eop_empty[i]; 
	always @(rx_error[i])  
		rx_error_variable[i]=rx_error[i];
	always @(rx_status[i])  
		rx_status_variable[i]=rx_status[i];
	always @(fcs_error[i])  
		fcs_error_variable[i]=fcs_error[i];
end
covergroup soponehot (input int position) @(posedge found_sop); 
	sop_onehot:coverpoint position iff(sop[position]==1 && $onehot(sop)) {
	bins position_range[]={[0:NUM_WORDS-1]};
	}
	option.per_instance=1;
endgroup 
covergroup eoponehot (input int position) @(posedge found_eop); 
	eop_onehot:coverpoint position iff(eop[position]==1 && $onehot(eop)) {
	bins position_range[]={[0:NUM_WORDS-1]};
	}
	option.per_instance=1;
endgroup 
//other values of sop & eop with no 2 consecutive bits being 1 

