        ignore_bins ILLEGAL_LEN_X_LENGTH_ERROR        = binsof(rx_status_pt) intersect {6} && binsof(rx_error) intersect {3};
        ignore_bins FC_FRAME_X_LENGTH_ERROR           = binsof(rx_status_pt) intersect {7} && binsof(rx_error) intersect {3};
        // if we corrupt the pfc/sfc frame with T char, extra 4 byte of FE added at the end so we cant hit SFC_PFC_FRAME_X_MALFORMED_ERROR  
        ignore_bins SFC_PFC_FRAME_X_MALFORMED_ERROR   = binsof(rx_status_pt) intersect {4} && binsof(rx_error) intersect {1};
        ignore_bins SFC_PFC_FRAME_X_OVERSIZE_ERROR    = binsof(rx_status_pt) intersect {4} && binsof(rx_error) intersect {2};}
	option.per_instance=1;
endgroup


function bit noconsecutive_bits(ref logic [NUM_WORDS-1:0] signal); 
	noconsecutive_bits=1;
	foreach (signal[i])
	begin 
		if(i==0)
		begin 
			//if($past(signal[NUM_WORDS-1],1,,@(posedge clk))!=='x) FIXME
			//	noconsecutive_bits= noconsecutive_bits&&(!($past(signal[NUM_WORDS-1],1,,@(posedge clk))&&signal[0]));
		end 
		else 
			noconsecutive_bits= noconsecutive_bits&&(!(signal[i]&&signal[i-1]));
	end 
	return(noconsecutive_bits);
endfunction 
//covergroup variables 
soponehot soponehot_c[NUM_WORDS]; 
eoponehot eoponehot_c[NUM_WORDS];
eop_aligned_bytes eop_aligned_bytes_c[NUM_WORDS];
eop_values eop_values_c;
sop_values sop_values_c;

initial begin 

	for(int i=0;i<NUM_WORDS;i++)begin 
		soponehot_c[i]=new(i);
		eoponehot_c[i]=new(i);
		eop_aligned_bytes_c[i]=new(empty_variable[i],rx_status_variable[i],rx_error_variable[i],fcs_error_variable[i]);
	end
	eop_values_c=new();
	sop_values_c=new();
end

endinterface : client_rx_if
